{
  "mechanism_id": "behavior_directed_soft_code_transition_kl",
  "version": "3.0.0",
  "title": "Behaviour-directed soft code-transition KL",
  "equation": "L = sum_{b: m_b=1} KL(p_t^b || p_s^b) / max(1, sum_b m_b), where p_s^b = softmax_c(-||s_b - e_c||^2 / tau) and p_t^b = softmax_c(-||t_b - e_c||^2 / tau).",
  "symbols": {
    "L": "Auxiliary loss for directed behaviour pairs.",
    "b": "Index of a source-target behaviour pair in the batch.",
    "m_b": "Pair-validity mask; 1 means valid and 0 means excluded.",
    "s_b": "Source item residual representation for pair b, supplied as source[b].",
    "t_b": "Target item residual representation for pair b, supplied as target[b].",
    "e_c": "Codebook row c, supplied as codebook[c].",
    "c": "Codebook-row index, from 1 to C.",
    "C": "Number of codebook rows.",
    "D": "Representation dimension.",
    "p_s^b": "Soft code assignment distribution for the source residual, computed over all codebook rows.",
    "p_t^b": "Soft code assignment distribution for the target residual, computed over all codebook rows.",
    "KL(p_t^b || p_s^b)": "Directed Kullback-Leibler divergence from target assignment distribution to source assignment distribution.",
    "tau": "Positive soft-assignment temperature; smaller values sharpen assignments."
  },
  "parameters": {
    "tau": 1.0,
    "epsilon": 1e-08
  },
  "target_paths": [
    "encoder",
    "codebook",
    "hard_sid_export"
  ],
  "hypotheses": [
    "For valid directed user-item behaviour pairs, training will organize residuals and codebook rows so that target soft assignments are predictable from source soft assignments; this may preserve or improve downstream candidate retrieval.",
    "This objective is a proposal, not evidence of downstream improvement. Select it only if a matched cold run improves Stage-3 recall@10 without reducing NDCG@10, and if hard-SID occupancy and retrieval checks show no collapse or regression.",
    "The auxiliary term must deliver a measurable codebook gradient on the host's assembled training path; a pre-assembly gradient alone does not qualify."
  ],
  "expected_failure_modes": [
    "The host overwrites the encoder gradient and the auxiliary term consequently produces no effective encoder update.",
    "The codebook gradient is zero, non-finite, or large enough to concentrate assignments into very few rows.",
    "Soft assignment KL improves while exported hard SIDs or Stage-3 candidate recall and ranking worsen.",
    "The directed objective is numerically unstable for sharp assignments or produces non-finite loss or gradients.",
    "The auxiliary term is effectively inactive, yielding bit-identical model parameters and exported SIDs to the control."
  ],
  "tests": [
    {
      "id": "finite_forward",
      "kind": "numeric",
      "statement": "On the declared synthetic case with at least one valid pair, the loss is finite and nonnegative."
    },
    {
      "id": "codebook_permutation",
      "kind": "metamorphic",
      "statement": "Permuting codebook rows leaves the loss unchanged within tolerance."
    },
    {
      "id": "directionality",
      "kind": "metamorphic",
      "statement": "For the declared non-degenerate synthetic case, exchanging source and target changes the loss beyond tolerance."
    },
    {
      "id": "all_pairs_masked",
      "kind": "metamorphic",
      "statement": "Masking every pair produces exactly zero loss and finite zero gradients."
    },
    {
      "id": "declared_gradients",
      "kind": "gradient",
      "statement": "With valid, non-degenerate pairs, gradients with respect to source, target, and codebook are finite and nonzero."
    },
    {
      "id": "host_assembled_codebook_gradient",
      "kind": "integration",
      "statement": "On the host's training path, the auxiliary term changes the assembled codebook gradient relative to the matched control; separately record the encoder gradient before and after host assembly."
    },
    {
      "id": "matched_cold_run",
      "kind": "integration",
      "statement": "Compare treatment and control using matched configuration and cold-run evaluation; accept only if Stage-3 recall@10 improves and NDCG@10 does not decline, with no hard-SID occupancy collapse."
    }
  ],
  "judges": [
    "contract_audit",
    "forward_oracle",
    "derivative_evidence",
    "property_checks",
    "integration_on_off"
  ],
  "forbidden_substitutions": [
    {
      "id": "symmetric_pair_distance",
      "pattern": "torch\\.nn\\.functional\\.kl_div\\s*\\(\\s*[^,]*p_s[^,]*,\\s*[^)]*p_t",
      "reason": "Reverses the declared KL direction and changes the mechanism's source-target asymmetry."
    },
    {
      "id": "detached_codebook",
      "pattern": "codebook\\s*=\\s*codebook\\.detach\\s*\\(",
      "reason": "Blocks the required codebook gradient, so the host's surviving gradient path cannot alter exported codes."
    },
    {
      "id": "hard_assignment",
      "pattern": "argmin\\s*\\(",
      "reason": "Replacing soft assignments with hard argmin assignments changes the objective and can remove useful gradients."
    },
    {
      "id": "encoder_only_detach",
      "pattern": "(source|target)\\s*=\\s*\\1\\.detach\\s*\\(",
      "reason": "Blocks a declared residual gradient target and changes the proposed end-to-end geometry update."
    }
  ],
  "invariants": [
    {
      "id": "permute_codebook",
      "transform": "permute_codebook",
      "expect": "unchanged",
      "tolerance": 1e-06
    },
    {
      "id": "swap_source_target",
      "transform": "swap_source_target",
      "expect": "changed",
      "tolerance": 1e-06
    },
    {
      "id": "mask_all",
      "transform": "mask_all",
      "expect": "zero",
      "tolerance": 0.0
    }
  ],
  "gradient_targets": {
    "source": "nonzero",
    "target": "nonzero",
    "codebook": "nonzero"
  },
  "inputs": {
    "source": {
      "shape": [
        8,
        4
      ],
      "seed": 11
    },
    "target": {
      "shape": [
        8,
        4
      ],
      "seed": 12
    },
    "codebook": {
      "shape": [
        6,
        4
      ],
      "seed": 13
    },
    "mask": {
      "seed": 17,
      "valid_fraction": 0.75
    }
  },
  "activation": {
    "kind": "term",
    "weight": 0.001
  },
  "differentiation": {
    "occupancy_preservation": "The objective compares soft assignment distributions rather than pulling every residual toward one code. This does not guarantee balanced hard-SID occupancy: measure per-level occupancy, entropy, and Gini, and reject the arm if occupancy collapses or retrieval regresses.",
    "vs_r8": [
      {
        "lane": "r8_01_directed_l1_transition_nce",
        "why": "Uses directed KL between full soft assignments over codebook rows, rather than contrastive classification over directed L1 code transitions."
      },
      {
        "lane": "r8_02_l1_next_item_prediction",
        "why": "Does not add an L1 next-item semantic prediction head or prediction target; it regularizes pairwise assignment distributions directly."
      },
      {
        "lane": "r8_03_successor_profile_js",
        "why": "Uses directed source-to-target assignment KL for individual behaviour pairs, not symmetric JS matching of successor profiles."
      },
      {
        "lane": "r8_04_behavior_conditioned_ot",
        "why": "Does not solve an entropic transport or quantizer assignment problem; it uses differentiable row-wise softmax assignments and a low-weight pair loss."
      },
      {
        "lane": "r8_05_three_level_distillation",
        "why": "Does not distil a teacher into three code levels; the declared objective is defined on the supplied residuals and codebook."
      },
      {
        "lane": "r8_06_train_graph_diffusion",
        "why": "Does not preserve graph diffusion distances; it uses directed observed behaviour pairs and their soft code assignments."
      },
      {
        "lane": "r8_07_hyperbolic_gyro",
        "why": "Uses Euclidean residual-to-codebook distances and no hyperbolic gyro-translation."
      },
      {
        "lane": "r8_08_hyperbolic_frechet",
        "why": "Uses no hyperbolic space or Frechet successor barycentres."
      },
      {
        "lane": "r8_09_hyperbolic_branching",
        "why": "Uses no radial hierarchy or branching constraint in hyperbolic space."
      },
      {
        "lane": "r8_10_hyperbolic_gw",
        "why": "Uses no graph-code Gromov-Wasserstein objective or hyperbolic graph matching."
      },
      {
        "lane": "r8_control",
        "why": "Unlike the untouched host control, this adds a low-weight behaviour-pair objective with an explicit codebook gradient; its downstream value must be established by matched evaluation."
      }
    ],
    "vs_reference_arm": "Unlike the gentle codebook-reaching geometry-transport reference arm, this mechanism directly regularizes the directed target-versus-source soft assignment distributions and tests that specific asymmetry. It does not claim an ER or downstream gain; the low activation weight and occupancy/retrieval selection criteria are intended to avoid repeating strong-assignment collapse, which must still be checked empirically."
  },
  "schema_version": 1,
  "provenance": {
    "authored_by": "researcher",
    "authored_at": "2026-10-21T00:00:00Z"
  }
}
